<?php
defined('ABSPATH')||exit;
final class Azula_Analytics_Admin{
private const S='azula-analytics';private const LAYOUT_META='_azula_analytics_layout_v1';
private const DEFAULT_LAYOUT=['sales-time','sales-channel','sessions-time','funnel','orders-time','aov-time','returning-time','payment','categories','discounts','brands','best-sellers','sizes','brand-category','gender'];
public static function init():void{add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_enqueue_scripts',[__CLASS__,'assets']);add_action('wp_ajax_azula_analytics_orders',[__CLASS__,'ajax_orders']);add_action('wp_ajax_azula_analytics_customers',[__CLASS__,'ajax_customers']);add_action('wp_ajax_azula_analytics_contributors',[__CLASS__,'ajax_contributors']);add_action('wp_ajax_azula_analytics_layout',[__CLASS__,'ajax_layout']);}
public static function menu():void{add_menu_page('Azula Analytics','Azula Analytics','view_woocommerce_reports',self::S,[__CLASS__,'render'],'dashicons-chart-area',56);add_submenu_page(self::S,'Top Categories','Top Categories','view_woocommerce_reports','azula-analytics-categories',[__CLASS__,'render_categories']);add_submenu_page(self::S,'Sales by Brand','Sales by Brand','view_woocommerce_reports','azula-analytics-brands',[__CLASS__,'render_brands']);add_submenu_page(self::S,'Brand × Category','Brand × Category','view_woocommerce_reports','azula-analytics-brand-category',[__CLASS__,'render_brand_category']);add_submenu_page(self::S,'Best Sellers','Best Sellers','view_woocommerce_reports','azula-analytics-best-sellers',[__CLASS__,'render_best_sellers']);add_submenu_page(self::S,'Best-Selling Sizes','Best-Selling Sizes','view_woocommerce_reports','azula-analytics-sizes',[__CLASS__,'render_sizes']);}
public static function assets(string $h):void{$page=sanitize_key(wp_unslash($_GET['page']??''));if(!in_array($page,[self::S,'azula-analytics-categories','azula-analytics-brands','azula-analytics-brand-category','azula-analytics-best-sellers','azula-analytics-sizes'],true))return;wp_enqueue_style('azula',AZULA_ANALYTICS_URL.'assets/css/admin.css',[],AZULA_ANALYTICS_VERSION);wp_enqueue_script('azula',AZULA_ANALYTICS_URL.'assets/js/dashboard.js',[],AZULA_ANALYTICS_VERSION,true);wp_localize_script('azula','AzulaAnalytics',['ajaxUrl'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('azula_analytics_admin'),'currency'=>'EGP']);}
private static function pct(float $a,?float $b):?float{return($b===null||abs($b)<.000001)?null:(($a-$b)/abs($b))*100;}
private static function delta(?float $p):string{if($p===null)return'';return'<span class="az-delta '.($p<0?'down':'up').'">'.($p>0?'↑':($p<0?'↓':'')).' '.esc_html(number_format_i18n(abs($p),1)).'%</span>';}
private static function money(float $n):string{return'EGP '.number_format_i18n($n,2);}
private static function unavailable(array $result):string{return'<span class="az-unavailable" title="'.esc_attr($result['error']??'GA4 unavailable').'">Unavailable</span>';}
private static function layout():array{$saved=get_user_meta(get_current_user_id(),self::LAYOUT_META,true);if(!is_array($saved))return self::DEFAULT_LAYOUT;$valid=array_values(array_intersect($saved,self::DEFAULT_LAYOUT));foreach(['best-sellers','sizes','brand-category']as$new_id){if(in_array($new_id,$valid,true))continue;$anchor=$new_id==='best-sellers'?'brands':($new_id==='sizes'?'best-sellers':'sizes');$pos=array_search($anchor,$valid,true);if($pos===false)$valid[]=$new_id;else array_splice($valid,$pos+1,0,[$new_id]);}foreach(self::DEFAULT_LAYOUT as$id)if(!in_array($id,$valid,true))$valid[]=$id;return$valid;}
private static function chart_controls():string{return'<div class="az-chart-controls"><select class="az-group" aria-label="Time grouping"><option value="day">By day</option><option value="week">By week</option><option value="month">By month</option></select><div class="az-view-toggle"><button type="button" class="button az-view active" data-view="line">Line</button><button type="button" class="button az-view" data-view="bar">Bar</button></div></div>';}
private static function order_button(int $count,string $report,string $bucket,string $title):string{if($count<1)return'0';return'<button type="button" class="az-order-count" data-report="'.esc_attr($report).'" data-bucket="'.esc_attr($bucket).'" data-title="'.esc_attr($title).'">'.esc_html(number_format_i18n($count)).'</button>';}
private static function table(array $rows,array $cols,?string $report=null):void{echo'<div class="az-table-wrap"><table class="widefat striped az-table"><thead><tr>';foreach($cols as$k=>$label)echo'<th>'.esc_html($label).'</th>';echo'</tr></thead><tbody>';if(!$rows)echo'<tr><td colspan="'.count($cols).'">No data for this period.</td></tr>';foreach($rows as$row){echo'<tr>';foreach($cols as$k=>$label){$v=$row[$k]??'';if($k==='sales'||$k==='discount_amount')$v=self::money((float)$v);elseif($k==='orders'&&$report)$v=self::order_button((int)$v,$report,(string)($row['bucket']??$row['label']??''),(string)($row['label']??'Orders'));elseif($k==='percent')$v=number_format_i18n((float)$v,1).'%';echo'<td>'.($k==='orders'&&$report?$v:esc_html((string)$v)).'</td>';}echo'</tr>';}echo'</tbody></table></div>';}
private static function with_percent(array $rows,int $total):array{foreach($rows as&$row)$row['percent']=$total?((int)$row['orders']/$total)*100:0.0;unset($row);return$rows;}
private static function card_open(string $id,string $class=''):void{echo'<article class="az-card '.esc_attr($class).'" data-card-id="'.esc_attr($id).'">';}
private static function card_close():void{echo'</article>';}

public static function ajax_orders():void{if(!current_user_can('view_woocommerce_reports'))wp_send_json_error(['message'=>'Not allowed.'],403);check_ajax_referer('azula_analytics_admin','nonce');$report=sanitize_key(wp_unslash($_POST['report']??''));$allowed=['channel','payment','brand','category','gender','coupon','orders','product','customer_orders','contributor'];if(!in_array($report,$allowed,true))wp_send_json_error(['message'=>'Invalid report.'],400);$bucket=sanitize_text_field(wp_unslash($_POST['bucket']??''));if($bucket==='')wp_send_json_error(['message'=>'Invalid bucket.'],400);$from=sanitize_text_field(wp_unslash($_POST['date_from']??''));$to=sanitize_text_field(wp_unslash($_POST['date_to']??''));$r=Azula_Analytics_Date_Range::from_request(['range'=>'custom','date_from'=>$from,'date_to'=>$to,'compare'=>'none']);$d=new Azula_Analytics_Woo_Data();$ids=$report==='contributor'?$d->contributor_order_ids($r,sanitize_key(wp_unslash($_POST['kind']??'')),$bucket):$d->order_ids_for_bucket($r,$report,$bucket);$page=max(1,(int)($_POST['page_num']??1));wp_send_json_success($d->order_details($ids,$page,25));}
public static function ajax_customers():void{if(!current_user_can('view_woocommerce_reports'))wp_send_json_error(['message'=>'Not allowed.'],403);check_ajax_referer('azula_analytics_admin','nonce');$bucket=sanitize_key(wp_unslash($_POST['bucket']??''));if(!in_array($bucket,['returning','all'],true))wp_send_json_error(['message'=>'Invalid customer group.'],400);$from=sanitize_text_field(wp_unslash($_POST['date_from']??''));$to=sanitize_text_field(wp_unslash($_POST['date_to']??''));$r=Azula_Analytics_Date_Range::from_request(['range'=>'custom','date_from'=>$from,'date_to'=>$to,'compare'=>'none']);$d=new Azula_Analytics_Woo_Data();$ids=$d->customer_ids_for_returning($r,$bucket);$page=max(1,(int)($_POST['page_num']??1));wp_send_json_success($d->customer_details($r,$ids,$page,25));}
public static function ajax_contributors():void{if(!current_user_can('view_woocommerce_reports'))wp_send_json_error(['message'=>'Not allowed.'],403);check_ajax_referer('azula_analytics_admin','nonce');$kind=sanitize_key(wp_unslash($_POST['kind']??''));$from=sanitize_text_field(wp_unslash($_POST['date_from']??''));$to=sanitize_text_field(wp_unslash($_POST['date_to']??''));$r=Azula_Analytics_Date_Range::from_request(['range'=>'custom','date_from'=>$from,'date_to'=>$to,'compare'=>'none']);$d=new Azula_Analytics_Woo_Data();if($kind==='size'){$gender=sanitize_text_field(wp_unslash($_POST['gender']??''));$category=sanitize_text_field(wp_unslash($_POST['category']??''));$size=sanitize_text_field(wp_unslash($_POST['size']??''));wp_send_json_success(['kind'=>'size','rows'=>$d->size_contributors($r,$gender,$category,$size)]);}if($kind==='brandcat'){$brand=sanitize_text_field(wp_unslash($_POST['brand']??''));$category=sanitize_text_field(wp_unslash($_POST['category']??''));wp_send_json_success(['kind'=>'brandcat','rows'=>$d->brand_category_contributors($r,$brand,$category)]);}wp_send_json_error(['message'=>'Invalid drill-down.'],400);}
public static function ajax_layout():void{if(!current_user_can('view_woocommerce_reports'))wp_send_json_error(['message'=>'Not allowed.'],403);check_ajax_referer('azula_analytics_admin','nonce');$mode=sanitize_key(wp_unslash($_POST['mode']??'save'));if($mode==='reset'){delete_user_meta(get_current_user_id(),self::LAYOUT_META);wp_send_json_success(['layout'=>self::DEFAULT_LAYOUT]);}$raw=isset($_POST['layout'])?(array)$_POST['layout']:[];$layout=array_values(array_intersect(array_map('sanitize_key',$raw),self::DEFAULT_LAYOUT));if(count($layout)!==count(self::DEFAULT_LAYOUT))wp_send_json_error(['message'=>'Invalid layout.'],400);update_user_meta(get_current_user_id(),self::LAYOUT_META,$layout);wp_send_json_success(['layout'=>$layout]);}


private static function report_url(string $page,array $r,array $extra=[]):string{return add_query_arg(array_merge(['page'=>$page,'range'=>'custom','date_from'=>$r['date_from'],'date_to'=>$r['date_to'],'compare'=>$r['comparison']??'none'],$extra),admin_url('admin.php'));}
private static function best_sellers_table(array $rows):void{echo'<div class="az-table-wrap"><table class="widefat striped az-table"><thead><tr><th>Product ID</th><th>Product</th><th>Items Sold</th><th>Orders</th><th>Sales</th><th>Stock Left</th></tr></thead><tbody>';if(!$rows)echo'<tr><td colspan="6">No products sold during this period.</td></tr>';foreach($rows as$row){$id=(int)$row['product_id'];$title=(string)$row['product'];$url=(string)$row['url'];$items=self::order_button((int)$row['items'],'product',(string)$id,$title);$orders=self::order_button((int)$row['orders'],'product',(string)$id,$title);$stock=$row['stock']===null?'—':number_format_i18n((float)$row['stock'],0).' qty';$parts=[];foreach(($row['stock_sizes']??[])as$sz=>$q)if((float)$q>0)$parts[]=number_format_i18n((float)$q,0).' '.esc_html($sz);$stock_html=esc_html($stock).($parts?'<small class="az-stock-sizes">'.implode(' · ',$parts).'</small>':'');echo'<tr><td><a target="_blank" rel="noopener" href="'.esc_url($url).'">'.esc_html((string)$id).'</a></td><td><a target="_blank" rel="noopener" href="'.esc_url($url).'">'.esc_html($title).'</a></td><td>'.$items.'</td><td>'.$orders.'</td><td>'.esc_html(self::money((float)$row['sales'])).'</td><td>'.$stock_html.'</td></tr>';}echo'</tbody></table></div>';}
private static function sizes_tables(array $data,bool $compact=false):void{$sections=$data['sections']??[];$preferred=$data['preferred']??[];foreach(['Women'=>'WOMEN','Men'=>'MEN','Unisex'=>'UNISEX']as$key=>$heading){if(empty($sections[$key]))continue;$rows=$sections[$key];if($compact)$rows=array_slice($rows,0,4,true);$others=[];foreach($rows as$row)foreach(array_keys($row['sizes'])as$size)if(!in_array($size,$preferred,true))$others[$size]=true;$columns=array_merge($preferred,array_keys($others));echo'<h3 class="az-size-heading">'.esc_html($heading).'</h3><div class="az-table-wrap"><table class="widefat striped az-table az-size-table"><thead><tr><th>Category</th>';foreach($columns as$size)echo'<th>'.esc_html(str_starts_with($size,'Other: ')?substr($size,7):$size).'</th>';echo'<th>Total</th></tr></thead><tbody>';foreach($rows as$row){echo'<tr><td>'.esc_html($row['category']).'</td>';foreach($columns as$size){$v=(int)($row['sizes'][$size]??0);echo'<td>'.($v?'<button type="button" class="az-contrib-count" data-kind="size" data-gender="'.esc_attr($key).'" data-category="'.esc_attr($row['category']).'" data-size="'.esc_attr($size).'" data-title="'.esc_attr($heading.' → '.$row['category'].' → '.$size).'">'.esc_html(number_format_i18n($v)).'</button>':'—').'</td>';}echo'<td><strong>'.esc_html(number_format_i18n((int)$row['total'])).'</strong></td></tr>';}echo'</tbody></table></div>';}if(!$sections)echo'<p class="az-empty">No classified clothing-size sales for this period.</p>';}
private static function simple_full_table(string $title,string $desc,string $page,array $rows,array $r,string $report):void{?><div class="wrap azula-wrap"><div class="az-head"><div><h1><?php echo esc_html($title);?></h1><p><?php echo esc_html($desc);?></p></div><a class="button" href="<?php echo esc_url(self::report_url(self::S,$r));?>">← Dashboard</a></div><div class="az-period"><?php echo esc_html($r['start']->format('M j, Y').' – '.$r['end']->format('M j, Y'));?></div><?php self::table($rows,['label'=>$report==='category'?'Category':'Brand','items'=>'Items Sold','orders'=>'Orders Containing '.($report==='category'?'Category':'Brand'),'sales'=>'Sales','percent'=>'% of Orders'],$report);?><div id="az-order-context" data-from="<?php echo esc_attr($r['date_from']);?>" data-to="<?php echo esc_attr($r['date_to']);?>"></div><?php self::modal_markup();?></div><?php }
public static function render_categories():void{if(!current_user_can('view_woocommerce_reports'))wp_die('Not allowed.');$r=Azula_Analytics_Date_Range::from_request($_GET);$d=new Azula_Analytics_Woo_Data();$n=$d->summary($r);self::simple_full_table('Top Categories','All existing category results for the selected period.','azula-analytics-categories',self::with_percent($d->categories($r),$n['orders']),$r,'category');}
public static function render_brands():void{if(!current_user_can('view_woocommerce_reports'))wp_die('Not allowed.');$r=Azula_Analytics_Date_Range::from_request($_GET);$d=new Azula_Analytics_Woo_Data();$n=$d->summary($r);self::simple_full_table('Sales by Brand','All existing brand results for the selected period.','azula-analytics-brands',self::with_percent($d->brands($r),$n['orders']),$r,'brand');}
private static function brand_category_table(array $rows):void{echo'<div class="az-table-wrap"><table class="widefat striped az-table"><thead><tr><th>Brand</th><th>Categories Sold</th><th>Total Items</th></tr></thead><tbody>';if(!$rows)echo'<tr><td colspan="3">No matching sales for this period.</td></tr>';foreach($rows as$b){$bits=[];foreach($b['categories']as$cat=>$qty)$bits[]='<span class="az-brandcat-chip">'.esc_html($cat).' <button type="button" class="az-contrib-count" data-kind="brandcat" data-brand="'.esc_attr($b['brand']).'" data-category="'.esc_attr($cat).'" data-title="'.esc_attr($b['brand'].' → '.$cat).'">'.esc_html(number_format_i18n($qty)).'</button></span>';echo'<tr><td><strong>'.esc_html($b['brand']).'</strong></td><td>'.implode(' · ',$bits).'</td><td>'.esc_html(number_format_i18n($b['total'])).'</td></tr>';}echo'</tbody></table></div>';}
public static function render_brand_category():void{if(!current_user_can('view_woocommerce_reports'))wp_die('Not allowed.');$r=Azula_Analytics_Date_Range::from_request($_GET);$d=new Azula_Analytics_Woo_Data();?><div class="wrap azula-wrap"><div class="az-head"><div><h1>Brand × Category Sales Performance</h1><p>Pieces sold by brand and approved analytics category. Zero categories are omitted.</p></div><a class="button" href="<?php echo esc_url(self::report_url(self::S,$r));?>">← Dashboard</a></div><div class="az-period"><?php echo esc_html($r['start']->format('M j, Y').' – '.$r['end']->format('M j, Y'));?></div><?php self::brand_category_table($d->brand_category_performance($r));?><div id="az-order-context" data-from="<?php echo esc_attr($r['date_from']);?>" data-to="<?php echo esc_attr($r['date_to']);?>"></div><?php self::modal_markup();?></div><?php }
public static function render_best_sellers():void{if(!current_user_can('view_woocommerce_reports'))wp_die('Not allowed.');$r=Azula_Analytics_Date_Range::from_request($_GET);$page=max(1,(int)($_GET['paged']??1));$search=sanitize_text_field(wp_unslash($_GET['s']??''));$d=new Azula_Analytics_Woo_Data();$data=$d->best_sellers_page($r,$page,25,$search);?><div class="wrap azula-wrap"><div class="az-head"><div><h1>Best Sellers</h1><p>Selected-period sales by canonical Woo parent Product ID. Stock Left is current inventory now.</p></div><a class="button" href="<?php echo esc_url(self::report_url(self::S,$r));?>">← Dashboard</a></div><div class="az-period"><?php echo esc_html($r['start']->format('M j, Y').' – '.$r['end']->format('M j, Y'));?></div><form method="get" class="az-report-search"><input type="hidden" name="page" value="azula-analytics-best-sellers"><input type="hidden" name="range" value="custom"><input type="hidden" name="date_from" value="<?php echo esc_attr($r['date_from']);?>"><input type="hidden" name="date_to" value="<?php echo esc_attr($r['date_to']);?>"><input type="search" name="s" value="<?php echo esc_attr($search);?>" placeholder="Product ID or title"><button class="button">Search</button></form><?php self::best_sellers_table($data['rows']);if($data['pages']>1){echo'<div class="az-pagination">';echo paginate_links(['base'=>add_query_arg('paged','%#%',self::report_url('azula-analytics-best-sellers',$r,$search!==''?['s'=>$search]:[])),'format'=>'','current'=>$data['page'],'total'=>$data['pages'],'type'=>'plain']);echo'</div>';}?><div id="az-order-context" data-from="<?php echo esc_attr($r['date_from']);?>" data-to="<?php echo esc_attr($r['date_to']);?>"></div><?php self::modal_markup();?></div><?php }
public static function render_sizes():void{if(!current_user_can('view_woocommerce_reports'))wp_die('Not allowed.');$r=Azula_Analytics_Date_Range::from_request($_GET);$d=new Azula_Analytics_Woo_Data();$data=$d->best_selling_sizes($r);?><div class="wrap azula-wrap"><div class="az-head"><div><h1>Best-Selling Sizes</h1><p>Pieces sold from purchased pa_size values, grouped by the existing Azula gender and approved analytics category classifiers. Footwear excluded.</p></div><a class="button" href="<?php echo esc_url(self::report_url(self::S,$r));?>">← Dashboard</a></div><div class="az-period"><?php echo esc_html($r['start']->format('M j, Y').' – '.$r['end']->format('M j, Y'));?></div><?php self::sizes_tables($data,false);?><div id="az-order-context" data-from="<?php echo esc_attr($r['date_from']);?>" data-to="<?php echo esc_attr($r['date_to']);?>"></div><?php self::modal_markup();?></div><?php }
private static function modal_markup():void{?><div class="az-modal" id="az-order-modal" hidden><div class="az-modal-backdrop" data-close="1"></div><div class="az-modal-panel" role="dialog" aria-modal="true" aria-labelledby="az-modal-title"><button type="button" class="az-modal-close" data-close="1" aria-label="Close">×</button><h2 id="az-modal-title">Orders</h2><div id="az-modal-body"><p>Loading…</p></div></div></div><?php }

public static function render():void{
if(!current_user_can('view_woocommerce_reports'))wp_die('Not allowed.');
$r=Azula_Analytics_Date_Range::from_request($_GET);$d=new Azula_Analytics_Woo_Data();$n=$d->summary($r);$tl=$d->timeline($r);$o=$r['compare_range']?$d->summary($r['compare_range']):null;$old_tl=$r['compare_range']?$d->timeline($r['compare_range']):[];$sp=$o?self::pct($n['total_sales'],$o['total_sales']):null;$op=$o?self::pct($n['orders'],$o['orders']):null;$ap=$o?self::pct($n['aov'],$o['aov']):null;
$ret=$d->returning_customers($r);$rtl=$d->returning_timeline($r);$ret_old=$r['compare_range']?$d->returning_customers($r['compare_range']):null;$old_rtl=$r['compare_range']?$d->returning_timeline($r['compare_range']):[];$retp=$ret_old?self::pct($ret['rate'],$ret_old['rate']):null;
$channels=$d->sales_by_channel($r);$payments=$d->payment_methods($r);$categories=self::with_percent($d->categories($r),$n['orders']);$discounts=$d->discounts($r);$coupons=$d->coupon_breakdown($r);$brands=self::with_percent($d->brands($r),$n['orders']);$genders=$d->genders($r);$best_sellers=$d->best_sellers($r,6);$sizes=$d->best_selling_sizes($r);$brand_category=$d->brand_category_performance($r);
$ga=new Azula_Analytics_GA4_Data();$live=['ok'=>true,'value'=>Azula_Analytics_Presence::count()];$visitors=$ga->total_visitors($r);$sess=$ga->sessions($r);$sess_tl=$ga->sessions_timeline($r);$funnel=$ga->funnel($r);$old_sess=$r['compare_range']?$ga->sessions($r['compare_range']):null;$old_sess_tl=$r['compare_range']?$ga->sessions_timeline($r['compare_range']):null;$old_funnel=$r['compare_range']?$ga->funnel($r['compare_range']):null;
$conversion=($funnel['ok']&&$funnel['sessions']>0)?($funnel['purchase']/$funnel['sessions'])*100:0.0;$old_conversion=($old_funnel&&$old_funnel['ok']&&$old_funnel['sessions']>0)?($old_funnel['purchase']/$old_funnel['sessions'])*100:null;$conversion_delta=$old_conversion!==null?self::pct($conversion,$old_conversion):null;$session_delta=($sess['ok']&&$old_sess&&$old_sess['ok'])?self::pct((float)$sess['value'],(float)$old_sess['value']):null;
$layout=self::layout();$cards=[];
ob_start();self::card_open('sales-time');?><div class="az-card-head"><div><h2>Total Sales Over Time</h2><div class="az-big"><?php echo esc_html(self::money($n['total_sales']));?></div></div><?php echo self::chart_controls();?></div><div class="az-chart-shell"><canvas data-chart="sales"></canvas><div class="az-tooltip"></div></div><?php self::card_close();$cards['sales-time']=ob_get_clean();
ob_start();self::card_open('sales-channel','az-table-card');?><h2>Sales by Channel</h2><p class="az-meta">Woo order/revenue truth + immutable Azula order attribution. One eligible order → one channel.</p><?php self::table($channels,['label'=>'Channel','orders'=>'Orders','sales'=>'Sales'],'channel');$channel_orders=array_sum(array_column($channels,'orders'));$channel_sales=array_sum(array_column($channels,'sales'));?><p class="az-meta">Reconciliation: <?php echo esc_html($channel_orders.' / '.$n['orders'].' orders · '.self::money($channel_sales).' / '.self::money($n['total_sales']));?></p><?php self::card_close();$cards['sales-channel']=ob_get_clean();
ob_start();self::card_open('sessions-time');?><div class="az-card-head"><div><h2>Sessions Over Time</h2><?php if($sess_tl['ok']):?><div class="az-big"><?php echo $sess['ok']?esc_html(number_format_i18n($sess['value'])):'—';?></div><p class="az-meta">GA4 reporting timezone: <?php echo esc_html($sess_tl['timezone']?:'Not returned');?></p><?php endif;?></div><?php echo self::chart_controls();?></div><?php if($sess_tl['ok']):?><div class="az-chart-shell"><canvas data-chart="sessions"></canvas><div class="az-tooltip"></div></div><?php else:echo wp_kses_post(self::unavailable($sess_tl));?><p class="az-meta"><?php echo esc_html($sess_tl['error']??'Google Analytics is unavailable.');?></p><?php endif;self::card_close();$cards['sessions-time']=ob_get_clean();
